<template><a-card class="panel-card form-card"><a-form layout="vertical" @finish="save"><a-form-item label="启用自动备份"><a-switch v-model:checked="enabled"/></a-form-item><a-form-item label="Cron 表达式"><a-input v-model:value="form.backup_cron"/></a-form-item><a-row :gutter="16"><a-col :span="12"><a-form-item label="保留天数"><a-input-number v-model:value="form.backup_retention" :min="1" style="width:100%"/></a-form-item></a-col><a-col :span="12"><a-form-item label="最大备份数"><a-input-number v-model:value="form.backup_max_count" :min="1" style="width:100%"/></a-form-item></a-col></a-row><a-checkbox v-model:checked="compress">压缩备份文件</a-checkbox><div style="margin-top:24px"><a-button type="primary" html-type="submit">保存备份设置</a-button></div></a-form></a-card></template><script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{message}from'ant-design-vue';import{get,put}from'../../services/http';import type{AnyMap}from'../../types';const form=reactive<AnyMap>({backup_cron:'0 3 * * *',backup_retention:7,backup_max_count:10}),enabled=ref(false),compress=ref(true);onMounted(async()=>{const d=await get<AnyMap>('/backup/config');Object.assign(form,d);enabled.value=d.backup_enabled===1;compress.value=d.backup_compress===1});async function save(){await put('/backup/config',{...form,backup_enabled:enabled.value?1:0,backup_compress:compress.value?1:0});message.success('备份设置已保存')}</script>
